defmodule Meta do
  @enforce_keys [:view]
  defstruct [:view]

  @type t :: %__MODULE__{
          view: View.t()
        }

  def from_map(m) do
    %Meta{
      view: View.from_map(m["view"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "view" => View.to_map(struct.view),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

defmodule TopLevel do
  @enforce_keys [:data, :meta]
  defstruct [:data, :meta]

  @type t :: %__MODULE__{
          data: [[integer() | String.t()]],
          meta: Meta.t()
        }

  def decode_data(value) when is_list(value), do: value
  def decode_data(_), do: {:error, "Unexpected type when decoding TopLevel.data"}

  def encode_data(value) when is_list(value), do: value
  def encode_data(_), do: {:error, "Unexpected type when encoding TopLevel.data"}

  def from_map(m) do
    %TopLevel{
      data: decode_data(m["data"]),
      meta: Meta.from_map(m["meta"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "data" => struct.data,
      "meta" => Meta.to_map(struct.meta),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end
